definition.script:
// Markdown to HTML Converter

var markdown = input.get("markdown");
var addWrapper = input.get("addWrapper") === "true";

if (!markdown) {
    log.error("Markdown input is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Markdown input is required");
    output.set("Html", "");
    tags.trigger("error");
} else {
    try {
        // Normalize line endings to \n
        var html = markdown.replace(/\r\n/g, '\n').replace(/\r/g, '\n');

        // Escape HTML special characters
        function escapeHtml(text) {
            return text
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;');
        }

        // Process fenced code blocks first (```) to protect them
        var codeBlocks = [];
        // Match ``` optionally followed by language, then content until closing ```
        var codeBlockPattern = /```(\w*)\n([\s\S]*?)\n```/g;
        var match;
        while ((match = codeBlockPattern.exec(html)) !== null) {
            var lang = match[1];
            var code = match[2];
            var langAttr = lang ? ' class="language-' + lang + '"' : '';
            var placeholder = '%%CODEBLOCK' + codeBlocks.length + '%%';
            codeBlocks.push('<pre><code' + langAttr + '>' + escapeHtml(code) + '</code></pre>');
            html = html.substring(0, match.index) + placeholder + html.substring(match.index + match[0].length);
            codeBlockPattern.lastIndex = match.index + placeholder.length;
        }

        // Also handle code blocks without newline after language
        codeBlockPattern = /```(\w*)([\s\S]*?)```/g;
        while ((match = codeBlockPattern.exec(html)) !== null) {
            var lang = match[1];
            var code = match[2].trim();
            var langAttr = lang ? ' class="language-' + lang + '"' : '';
            var placeholder = '%%CODEBLOCK' + codeBlocks.length + '%%';
            codeBlocks.push('<pre><code' + langAttr + '>' + escapeHtml(code) + '</code></pre>');
            html = html.substring(0, match.index) + placeholder + html.substring(match.index + match[0].length);
            codeBlockPattern.lastIndex = match.index + placeholder.length;
        }

        // Process inline code (`) - protect these too
        var inlineCodes = [];
        html = html.replace(/`([^`\n]+)`/g, function(m, code) {
            var idx = inlineCodes.length;
            inlineCodes.push('<code>' + escapeHtml(code) + '</code>');
            return '%%INLINECODE' + idx + '%%';
        });

        // Headers (must be at start of line)
        html = html.replace(/^######\s+(.+)$/gm, '<h6>$1</h6>');
        html = html.replace(/^#####\s+(.+)$/gm, '<h5>$1</h5>');
        html = html.replace(/^####\s+(.+)$/gm, '<h4>$1</h4>');
        html = html.replace(/^###\s+(.+)$/gm, '<h3>$1</h3>');
        html = html.replace(/^##\s+(.+)$/gm, '<h2>$1</h2>');
        html = html.replace(/^#\s+(.+)$/gm, '<h1>$1</h1>');

        // Horizontal rules
        html = html.replace(/^(---|___|\*\*\*)\s*$/gm, '<hr/>');

        // Blockquotes
        html = html.replace(/^>\s*(.+)$/gm, '<blockquote>$1</blockquote>');
        html = html.replace(/<\/blockquote>\n<blockquote>/g, '\n');

        // Images (before links)
        html = html.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, '<img src="$2" alt="$1"/>');

        // Links
        html = html.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');

        // Bold (** or __)
        html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
        html = html.replace(/__([^_]+)__/g, '<strong>$1</strong>');

        // Italic (* or _) - be careful not to match inside words
        html = html.replace(/\*([^*]+)\*/g, '<em>$1</em>');
        html = html.replace(/\b_([^_]+)_\b/g, '<em>$1</em>');

        // Strikethrough
        html = html.replace(/~~([^~]+)~~/g, '<del>$1</del>');

        // Process lists
        var lines = html.split('\n');
        var result = [];
        var inList = null;

        for (var i = 0; i < lines.length; i++) {
            var line = lines[i];
            var ulMatch = line.match(/^\s*[\*\-\+]\s+(.+)$/);
            var olMatch = line.match(/^\s*\d+\.\s+(.+)$/);

            if (ulMatch) {
                if (inList !== 'ul') {
                    if (inList) result.push('</' + inList + '>');
                    result.push('<ul>');
                    inList = 'ul';
                }
                result.push('<li>' + ulMatch[1] + '</li>');
            } else if (olMatch) {
                if (inList !== 'ol') {
                    if (inList) result.push('</' + inList + '>');
                    result.push('<ol>');
                    inList = 'ol';
                }
                result.push('<li>' + olMatch[1] + '</li>');
            } else {
                if (inList) {
                    result.push('</' + inList + '>');
                    inList = null;
                }
                result.push(line);
            }
        }
        if (inList) result.push('</' + inList + '>');
        html = result.join('\n');

        // Paragraphs - wrap text blocks not already in block elements
        var blocks = html.split(/\n\n+/);
        var finalBlocks = [];
        for (var b = 0; b < blocks.length; b++) {
            var block = blocks[b].trim();
            if (!block) continue;

            // Don't wrap if already a block element or placeholder
            if (block.match(/^<(h[1-6]|ul|ol|blockquote|pre|hr|div|table|p)/) || 
                block.indexOf('%%CODEBLOCK') === 0) {
                finalBlocks.push(block);
            } else {
                block = block.replace(/\n/g, '<br/>\n');
                finalBlocks.push('<p>' + block + '</p>');
            }
        }
        html = finalBlocks.join('\n\n');

        // Restore code blocks
        for (var c = 0; c < codeBlocks.length; c++) {
            html = html.replace('%%CODEBLOCK' + c + '%%', codeBlocks[c]);
            html = html.replace('<p>%%CODEBLOCK' + c + '%%</p>', codeBlocks[c]);
        }

        // Restore inline code
        for (var ic = 0; ic < inlineCodes.length; ic++) {
            html = html.replace(new RegExp('%%INLINECODE' + ic + '%%', 'g'), inlineCodes[ic]);
        }

        if (addWrapper) {
            html = '<div class="markdown-body">\n' + html + '\n</div>';
        }

        output.set("Html", html);
        output.set("InputLength", markdown.length);
        output.set("OutputLength", html.length);
        output.set("HasErrors", false);
        output.set("ErrorMessage", "");
        log.info("Converted markdown to HTML: " + html.length + " chars");
        tags.trigger("success");

    } catch (ex) {
        log.error("Markdown conversion failed: " + ex.message);
        output.set("HasErrors", true);
        output.set("ErrorMessage", ex.message);
        output.set("Html", "");
        tags.trigger("error");
    }
}
